from collections import Counter
class Solution:
 def uniqueOccurrences(self,arr):
  c=Counter(arr).values();return len(c)==len(set(c))

class Solution:
 def minCostToMoveChips(self,position):
  even=sum(x%2==0 for x in position);return min(even,len(position)-even)

class Solution:
 def balancedStringSplit(self,s):
  bal=ans=0
  for c in s:
   bal+=1 if c=='L' else -1
   if bal==0:ans+=1
  return ans

class Solution:
 def checkStraightLine(self,coordinates):
  x0,y0=coordinates[0];x1,y1=coordinates[1]
  return all((x-x0)*(y1-y0)==(y-y0)*(x1-x0) for x,y in coordinates[2:])

class Solution:
 def oddCells(self,m,n,indices):
  rows=[0]*m;cols=[0]*n
  for r,c in indices:rows[r]+=1;cols[c]+=1
  return sum((rows[r]+cols[c])%2 for r in range(m) for c in range(n))

class Solution:
 def shiftGrid(self,grid,k):
  m=len(grid);n=len(grid[0]);a=[x for row in grid for x in row];k%=len(a);a=a[-k:]+a[:-k] if k else a
  return [a[i*n:(i+1)*n] for i in range(m)]

class Solution:
 def minTimeToVisitAllPoints(self,points):
  return sum(max(abs(b[0]-a[0]),abs(b[1]-a[1])) for a,b in zip(points,points[1:]))

class Solution:
 def tictactoe(self,moves):
  board=[['']*3 for _ in range(3)]
  for i,(r,c) in enumerate(moves):
   p='A' if i%2==0 else 'B';board[r][c]=p
   if any(all(board[r][j]==p for j in range(3)) for r in range(3)) or any(all(board[j][c]==p for j in range(3)) for c in range(3)) or all(board[j][j]==p for j in range(3)) or all(board[j][2-j]==p for j in range(3)):return p
  return 'Draw' if len(moves)==9 else 'Pending'

class Solution:
 def subtractProductAndSum(self,n):
  prod=1;total=0
  while n:
   d=n%10;prod*=d;total+=d;n//=10
  return prod-total

class Solution:
 def findNumbers(self,nums):
  ans=0
  for x in nums:
   digits=0
   while x:x//=10;digits+=1
   if digits%2==0:ans+=1
  return ans
